# Analyze where 4s appear in test input
from collections import defaultdict

test_grid = G['Test input (26x15)']

left_4s_by_row = defaultdict(set)  # row -> cols on left (0-6)
right_4s_by_row = defaultdict(set)  # row -> cols on right (8-14), local indices

for r in range(26):
    row = test_grid[r]
    for c in range(7):  # Left side
        if row[c] == 4:
            left_4s_by_row[r].add(c)
    for c in range(7):  # Right side (local indices)
        global_c = 8 + c
        if global_c < 15 and row[global_c] == 4:
            right_4s_by_row[r].add(c)

print("Rows with 4s on LEFT side:")
for r in sorted(left_4s_by_row.keys()):
    print(f"Row {r}: local cols {sorted(left_4s_by_row[r])}, values={test_grid[r][:7]}")

print("\n\nRows with 4s on RIGHT side:")
for r in sorted(right_4s_by_row.keys()):
    print(f"Row {r}: local cols {sorted(right_4s_by_row[r])}, values={test_grid[r][8:]}")

# What ARE these matching values?
from collections import defaultdict

col_value_matches = defaultdict(set)
for c in range(7):
    for r in range(26):
        left_val = test_grid[r][c]
        right_val = test_grid[r][8+c]
        if left_val == right_val and (left_val != 8 or left_val != 8):  # Non-8 matching
            col_value_matches[(c, left_val)].add(r)

print("Non-trivial value matches between left/right:")
for key, rows in sorted(col_value_matches.items()):
    c, val = key
    print(f"Cols {c} both have value {val}: rows {sorted(rows)}")

# Check specifically for 4-4 matches
